import{_ as t,o as r,c as s,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p="/assets/a9aeb16e40ec0ef0.BKnUVxh3.png",a="/assets/5891fffabedd0b4f.B4jMXEWI.png",g=JSON.parse('{"title":"CentOS 8 EOL如何切换源","description":"","frontmatter":{"title":"CentOS 8 EOL如何切换源"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/centos-8-eol-switch-mirror.md","filePath":"ops-knowledge-base/operating-system/linux/centos-8-eol-switch-mirror.md","lastUpdated":1788259091000}'),n={name:"ops-knowledge-base/operating-system/linux/centos-8-eol-switch-mirror.md"};function l(i,e,m,c,u,_){return r(),s("div",null,[...e[0]||(e[0]=[o('<p>Centos8于2021年年底停止了服务，在使用yum源安装时候，出现以下报错：</p><p><img src="'+p+'" alt=""></p><p>解决方法:</p><p>1、进入yum的repos目录</p><p>cd /etc/yum.repos.d/</p><p>2、修改所有的CentOS文件内容</p><p>sed -i &#39;s/mirrorlist/#mirrorlist/g&#39; /etc/yum.repos.d/CentOS-*</p><p>sed -i &#39;s|#baseurl=<a href="http://mirror.centos.org%7Cbaseurl=http" target="_blank" rel="noreferrer">http://mirror.centos.org|baseurl=http</a>😕/vault.centos.org|g&#39; /etc/yum.repos.d/CentOS-*</p><p>3、更新yum源为阿里镜像</p><p>yum clean all &amp;&amp; yum makecache</p><p>yum -y install wget</p><p>wget -O /etc/yum.repos.d/CentOS-Base.repo <a href="https://mirrors.aliyun.com/repo/Centos-vault-8.5.2111.repo" target="_blank" rel="noreferrer">https://mirrors.aliyun.com/repo/Centos-vault-8.5.2111.repo</a></p><p>yum -y install epel-release</p><p>切换为阿里源后测试可以正常使用yum下载想要使用的工具了。</p><p><img src="'+a+'" alt=""></p>',15)])])}const y=t(n,[["render",l]]);export{g as __pageData,y as default};
